{{ config(schema='silver', materialized='view', tags=['file_feed', 'healthcare.pharmacy_claims', 'generated']) }}

-- Silver: every accepted row of every healthcare.pharmacy_claims file, typed by the contract.
with deliveries as (
    select distinct on (d.file_sha256)
        d.file_sha256,
        d.source_key,
        coalesce(d.file_date, (d.received_at at time zone 'UTC')::date) as file_date,
        d.received_at
    from {{ source('ops', 'intake_delivery') }} as d
    where d.feed = 'healthcare.pharmacy_claims'
    order by
        d.file_sha256,
        coalesce(d.file_date, (d.received_at at time zone 'UTC')::date) desc,
        d.received_at desc,
        d.source_key desc
)

select
    b.file_sha256,
    b.row_number,
    d.source_key,
    d.file_date,
    d.received_at,
    f.contract_version,
    b.record ->> 'rx_claim_id' as "rx_claim_id",
    b.record ->> 'member_id' as "member_id",
    (b.record ->> 'fill_date')::date as "fill_date",
    b.record ->> 'ndc' as "ndc",
    (b.record ->> 'days_supply')::numeric as "days_supply",
    (b.record ->> 'quantity')::numeric as "quantity",
    (b.record ->> 'paid_amount')::numeric as "paid_amount",
    b.record ->> 'pharmacy_npi' as "pharmacy_npi"
from {{ source('bronze', 'csv_record') }} as b
inner join {{ source('ops', 'intake_file') }} as f
    on f.feed = b.feed and f.file_sha256 = b.file_sha256
inner join deliveries as d on d.file_sha256 = b.file_sha256
where b.feed = 'healthcare.pharmacy_claims'
